  'fig-comparaison': [
    { oeuvre: 'boite', q: '« Le patio ressemblait à un puits de lumière. » De quelle figure s’agit-il ?',
      opts: ['Une comparaison', 'Une métaphore', 'Une personnification', 'Une métonymie'], ans: 0,
      exp: 'La comparaison rapproche deux éléments AU MOYEN d’un outil : comme, tel, semblable à, ressembler à, on dirait. Ici, « ressemblait à ».' },
    { oeuvre: 'condamne', q: 'Quels sont les trois éléments d’une comparaison complète ?',
      opts: ['Le comparé, l’outil de comparaison, le comparant', 'Le sujet, le verbe, le complément', 'L’image, le son, le sens', 'Le thème, la thèse, l’argument'], ans: 0,
      exp: 'Dans « les prisonniers étaient comme un troupeau » : comparé = les prisonniers, outil = comme, comparant = un troupeau. Nommer les trois en copie montre qu’on maîtrise la figure.' },
    { oeuvre: 'antigone', q: 'Comment ne jamais confondre comparaison et métaphore ?',
      opts: ['En cherchant l’outil de comparaison : s’il est présent, c’est une comparaison', 'En regardant la longueur de la phrase', 'En vérifiant le temps du verbe', 'En comptant les adjectifs'], ans: 0,
      exp: 'C’est la confusion la plus coûteuse du régional, et le test tient en une seconde. Outil présent : comparaison. Outil absent : métaphore. Rien d’autre à vérifier.' },
    { oeuvre: 'condamne', q: 'Pourquoi Hugo compare-t-il les condamnés à un troupeau qu’on mène ?',
      opts: ['Pour dénoncer une justice qui traite des hommes comme des bêtes', 'Pour préciser leur nombre', 'Pour rendre la scène plus gaie', 'Pour décrire leurs vêtements'], ans: 0,
      exp: 'Une comparaison n’est jamais décorative dans un roman à thèse : elle transporte un jugement. Le correcteur attend toujours l’effet, pas seulement le nom de la figure.' },
    { oeuvre: 'boite', q: 'Transforme en comparaison : « Cette cour était une prison. »',
      opts: ['Cette cour était comme une prison.', 'Cette cour, prison des enfants.', 'La prison de cette cour.', 'Cette cour emprisonnait.'], ans: 0,
      exp: 'Il suffit d’introduire l’outil. La phrase de départ, sans outil, était une métaphore : on passe donc de la métaphore à la comparaison en ajoutant « comme ».' },
  ],

  'fig-metaphore': [
    { oeuvre: 'boite', q: '« Sa mémoire était un coffre rempli de trésors. » Quelle figure ?',
      opts: ['Une métaphore', 'Une comparaison', 'Une litote', 'Une périphrase'], ans: 0,
      exp: 'Aucun outil de comparaison : le comparant est directement substitué au comparé. C’est une métaphore.' },
    { oeuvre: 'condamne', q: 'Qu’appelle-t-on une métaphore filée ?',
      opts: ['Une métaphore prolongée sur plusieurs phrases par des mots du même univers', 'Une métaphore très courte', 'Une métaphore employée deux fois', 'Une métaphore suivie d’une comparaison'], ans: 0,
      exp: 'Elle se reconnaît à la continuité du champ lexical : si l’image de la prison-tombeau se poursuit sur tout un paragraphe, la métaphore est filée. Repérer le filage vaut toujours des points.' },
    { oeuvre: 'antigone', q: 'Dans « Antigone est la petite maigre qui va mourir », y a-t-il métaphore ?',
      opts: ['Non : c’est une désignation, pas une image', 'Oui : « petite maigre » est une métaphore', 'Oui : c’est une métaphore filée', 'Non : c’est une comparaison'], ans: 0,
      exp: 'Attention à ne pas voir des figures partout. Une métaphore suppose un transfert d’un domaine à un autre. Ici, le groupe décrit littéralement le personnage : aucun transfert.' },
    { oeuvre: 'boite', q: 'Quel effet la métaphore produit-elle que la comparaison ne produit pas ?',
      opts: ['Elle fusionne les deux réalités au lieu de les rapprocher', 'Elle allonge la phrase', 'Elle rend le texte plus clair', 'Elle marque une hésitation'], ans: 0,
      exp: 'La comparaison dit « ceci est comme cela » et maintient la distance. La métaphore dit « ceci EST cela » : l’identification est plus brutale, donc plus forte.' },
    { oeuvre: 'condamne', q: 'Transforme en métaphore : « La prison était comme un tombeau. »',
      opts: ['La prison était un tombeau.', 'La prison ressemblait à un tombeau.', 'La prison, tel un tombeau.', 'On aurait dit un tombeau.'], ans: 0,
      exp: 'Supprimer l’outil suffit. Les trois autres réponses conservent un outil (ressemblait à, tel, on aurait dit) et restent donc des comparaisons.' },
  ],

